import React, { useState, useEffect, useContext } from "react";
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  doc,
} from "firebase/firestore";
import { db } from "../firebase";
import { Table } from "react-bootstrap";
import { useAuth } from "../AuthContext";
import AppContext from "./AppContext";

const LiveUser = () => {
  const [loggedUsers, setLoggedUsers] = useState([]);
  const [quizDetails, setQuizDetails] = useState({});
  const { keyExam } = useContext(AppContext); // quizID
  const { user } = useAuth();

  // Tworzenie nowej sesji po zalogowaniu użytkownika
  const createSession = async () => {
    if (user && keyExam) {
      const sessionRef = collection(db, "sessions");
      try {
        const docRef = await addDoc(sessionRef, {
          userID: user.userName,
          isActive: true,
          quizID: keyExam,
          timestamp: new Date(),
        });
        console.log("Utworzono sesję z ID:", docRef.id);
      } catch (error) {
        console.error("Błąd przy tworzeniu sesji:", error);
      }
    }
  };

  // Nasłuchiwanie aktywnych użytkowników
  const listenToActiveSessions = () => {
    if (!keyExam) {
      console.error("Brak quizID. Nie można nasłuchiwać sesji.");
      return;
    }

    console.log("Nasłuchiwanie aktywnych sesji dla quizID:", keyExam);

    const sessionsCollection = collection(db, "sessions");
    const q = query(
      sessionsCollection,
      where("quizID", "==", keyExam),
      where("isActive", "==", true)
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const usersData = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
      console.log("Zalogowani użytkownicy:", usersData);
      setLoggedUsers(usersData);
    });

    return unsubscribe;
  };

  // Zakończenie sesji przy wylogowaniu
  const endSession = async () => {
    if (user && keyExam) {
      const sessionsCollection = collection(db, "sessions");
      const sessionRef = doc(sessionsCollection, user.userName);

      try {
        await updateDoc(sessionRef, {
          isActive: false,
        });
        console.log("Zakończono sesję użytkownika:", user.userName);
      } catch (error) {
        console.error("Błąd przy zakończeniu sesji:", error);
      }
    }
  };

  useEffect(() => {
    if (keyExam) {
      const unsubscribe = listenToActiveSessions();
      return () => {
        if (unsubscribe) unsubscribe();
      };
    }
  }, [keyExam]);

  useEffect(() => {
    if (user) {
      createSession();
      return () => {
        endSession();
      };
    }
  }, [user, keyExam]);

  return (
    <div className="admin-panel">
      <h2>
        Użytkownicy pracujący nad arkuszem {quizDetails.Qualification}{" "}
        {quizDetails.Year}/{quizDetails.Session}
      </h2>
      <Table striped bordered hover>
        <thead>
          <tr>
            <th>ID Użytkownika</th>
            <th>Imię i Nazwisko</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {loggedUsers.length > 0 ? (
            loggedUsers.map((user) => (
              <tr key={user.id}>
                <td>{user.userID}</td>
                <td>{user.userID}</td>
                <td>Aktywny</td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="3">Brak zalogowanych użytkowników do tego egzaminu.</td>
            </tr>
          )}
        </tbody>
      </Table>
    </div>
  );
};

export default LiveUser;
